[{"order":1,"type":"heading","text":"Avoiding Bridge/JSI Bottlenecks and Unnecessary Re-renders in React Native"},{"order":2,"type":"paragraph","text":"React Native performance heavily relies on minimizing cross-language communication bottlenecks and preventing redundant component re-renders. This tutorial explores advanced techniques using React.memo, useMemo, and useCallback to optimize your applications."},{"order":3,"type":"subheading","text":"Understanding the Bridge and JSI Bottlenecks"},{"order":4,"type":"paragraph","text":"In the legacy React Native architecture, the JavaScript thread and native thread communicate asynchronously across the React Native Bridge by serializing JSON messages. Passing large data structures frequently causes latency. The modern Architecture introduces the JavaScript Interface (JSI), allowing direct synchronous calls between JS and C++ native modules. However, excessive data serialization or frequent state updates still cause frame drops."},{"order":5,"type":"subheading","text":"Preventing Unnecessary Re-renders with React.memo"},{"order":6,"type":"paragraph","text":"By default, when a parent component re-renders, all its children re-render as well. React.memo is a higher-order component that memorizes the rendered output of a functional component, skipping re-renders if the props have not changed."},{"order":7,"type":"code","text":"import React from 'react';
import { Text, View } from 'react-native';

interface ListItemProps {
  title: string;
}

export const ListItem = React.memo(({ title }: ListItemProps) => {
  console.log('ListItem rendered: ' + title);
  return (
    <View>
      <Text>{title}</Text>
    </View>
  );
});"},{"order":8,"type":"subheading","text":"Caching Expensive Computations with useMemo"},{"order":9,"type":"paragraph","text":"Complex calculations executed on the JavaScript thread can block UI responsiveness. The useMemo hook caches the result of a calculation between re-renders, recalculating only when its dependencies change."},{"order":10,"type":"code","text":"import React, { useMemo, useState } from 'react';
import { Text, View } from 'react-native';

export const ExpensiveList = ({ items }: { items: number[] }) => {
  const [filter, setFilter] = useState(10);

  const filteredItems = useMemo(() => {
    console.log('Calculating filtered items...');
    return items.filter(item => item > filter);
  }, [items, filter]);

  return (
    <View>
      {filteredItems.map(item => (
        <Text key={item}>{item}</Text>
      ))}
    </View>
  );
};"},{"order":11,"type":"subheading","text":"Stabilizing Function References with useCallback"},{"order":12,"type":"paragraph","text":"Functions in JavaScript are re-created on every render cycle. Passing an inline function as a prop to a memoized child component breaks React.memo because the reference changes every time. The useCallback hook returns a memoized version of the callback that only changes if one of the dependencies has changed."},{"order":13,"type":"code","text":"import React, { useState, useCallback } from 'react';
import { Button, View } from 'react-native';
import { ListItem } from './ListItem';

export const ParentComponent = () => {
  const [count, setCount] = useState(0);

  const handlePress = useCallback(() => {
    console.log('Button pressed');
  }, []);

  return (
    <View>
      <Button title={'Count: ' + count} onPress={() => setCount(count + 1)} />
      <ListItem title="Static Title" onPress={handlePress} />
    </View>
  );
};"},{"order":14,"type":"subheading","text":"Best Practices Summary"},{"order":15,"type":"bullet_point","text":"Do not prematurely optimize every component with React.memo; use it primarily for heavy lists or deeply nested component trees."},{"order":16,"type":"bullet_point","text":"Always pair React.memo child components with useCallback for passed functions and useMemo for passed object/array props."},{"order":17,"type":"bullet_point","text":"Keep state as local as possible to avoid triggering sweeping re-renders across the entire root component hierarchy."}]
